export function getQuestionCount(
  type: 'especialidades' | 'temas' | 'focos' | 'subfocos' | 'subSubfocos',
  name: string
): number {
  const map = hierarchyQuestionCounts[type];
  if (!map) return 0;
  return (map as Record<string, number>)[name] || 0;
}
